def perturbed_fibonacci(f, n, initial=(1,1)):
    if n <= 1: return initial[n]
    prev2, prev1 = initial
    for k in range(2, n+1):
        prev2, prev1 = prev1, prev1 + prev2 + f(k-2)
    return prev1

def constant_pert_closed(c, n):
    def fib(k):
        a, b = 0, 1
        for _ in range(k): a, b = b, a+b
        return a
    return (1+c)*fib(n+1) - c
